"<script>/* Jelszómentes Otthon-szerkesztő. A háttérfrissítés nem írja felül a szerkesztést. */\n"
"const LoxoneHome = (() => {\n"
"    'use strict';\n"
"    const icons = [{\"id\":\"refrigerator\",\"hu\":\"Hűtőszekrény\",\"en\":\"Refrigerator\"},{\"id\":\"washing-machine\",\"hu\":\"Mosógép\",\"en\":\"Washing machine\"},{\"id\":\"tumble-dryer\",\"hu\":\"Szárítógép\",\"en\":\"Tumble dryer\"},{\"id\":\"dishwasher\",\"hu\":\"Mosogatógép\",\"en\":\"Dishwasher\"},{\"id\":\"oven\",\"hu\":\"Sütő\",\"en\":\"Oven\"},{\"id\":\"hob\",\"hu\":\"Főzőlap\",\"en\":\"Induction hob\"},{\"id\":\"ac-indoor\",\"hu\":\"Beltéri klíma\",\"en\":\"Indoor air conditioner\"},{\"id\":\"ac-dual\",\"hu\":\"Dual klíma\",\"en\":\"Dual air conditioner\"},{\"id\":\"ac-trial\",\"hu\":\"Trial klíma\",\"en\":\"Triple air conditioner\"},{\"id\":\"ac-portable\",\"hu\":\"Mobil klíma\",\"en\":\"Portable air conditioner\"},{\"id\":\"ev-charger\",\"hu\":\"Elektromos autótöltő\",\"en\":\"EV charger\"},{\"id\":\"ups\",\"hu\":\"UPS\",\"en\":\"UPS\"},{\"id\":\"dehumidifier\",\"hu\":\"Páramentesítő\",\"en\":\"Dehumidifier\"},{\"id\":\"tv\",\"hu\":\"TV\",\"en\":\"Television\"},{\"id\":\"ventilation\",\"hu\":\"Szellőztető\",\"en\":\"Ventilation unit\"},{\"id\":\"fan\",\"hu\":\"Ventilátor\",\"en\":\"Fan\"},{\"id\":\"extractor-hood\",\"hu\":\"Elszívó\",\"en\":\"Extractor hood\"},{\"id\":\"wine-fridge\",\"hu\":\"Borhűtő\",\"en\":\"Wine cooler\"},{\"id\":\"radiator\",\"hu\":\"Fűtőtest\",\"en\":\"Radiator\"},{\"id\":\"lamp\",\"hu\":\"Lámpa\",\"en\":\"Lamp\"},{\"id\":\"heat-pump\",\"hu\":\"Hőszivattyú\",\"en\":\"Heat pump\"},{\"id\":\"water-heater\",\"hu\":\"Bojler\",\"en\":\"Water heater\"},{\"id\":\"underfloor-heating\",\"hu\":\"Padlófűtés\",\"en\":\"Underfloor heating\"},{\"id\":\"freezer\",\"hu\":\"Fagyasztó\",\"en\":\"Freezer\"},{\"id\":\"coffee-machine\",\"hu\":\"Kávéfőző\",\"en\":\"Coffee machine\"},{\"id\":\"kettle\",\"hu\":\"Vízforraló\",\"en\":\"Kettle\"},{\"id\":\"microwave\",\"hu\":\"Mikrohullámú sütő\",\"en\":\"Microwave\"},{\"id\":\"vacuum-cleaner\",\"hu\":\"Porszívó\",\"en\":\"Vacuum cleaner\"},{\"id\":\"robot-vacuum\",\"hu\":\"Robotporszívó\",\"en\":\"Robot vacuum\"},{\"id\":\"computer\",\"hu\":\"Számítógép\",\"en\":\"Computer\"},{\"id\":\"nas\",\"hu\":\"NAS\",\"en\":\"NAS\"},{\"id\":\"circulation-pump\",\"hu\":\"Keringetőszivattyú\",\"en\":\"Circulation pump\"},{\"id\":\"pool-pump\",\"hu\":\"Medenceszivattyú\",\"en\":\"Pool pump\"},{\"id\":\"towel-heater\",\"hu\":\"Törölközőszárító\",\"en\":\"Towel warmer\"},{\"id\":\"socket\",\"hu\":\"Konnektor\",\"en\":\"Power socket\"},{\"id\":\"thermostat\",\"hu\":\"Termosztát\",\"en\":\"Thermostat\"},{\"id\":\"temperature\",\"hu\":\"Hőmérséklet\",\"en\":\"Temperature\"},{\"id\":\"humidity\",\"hu\":\"Páratartalom\",\"en\":\"Humidity\"},{\"id\":\"co2\",\"hu\":\"CO₂ / levegőminőség\",\"en\":\"CO2 / air quality\"},{\"id\":\"water-level\",\"hu\":\"Vízszint\",\"en\":\"Water level\"},{\"id\":\"electric-car\",\"hu\":\"Elektromos autó\",\"en\":\"Electric car\"},{\"id\":\"garage-door\",\"hu\":\"Garázskapu\",\"en\":\"Garage door\"},{\"id\":\"gate\",\"hu\":\"Kertkapu\",\"en\":\"Garden gate\"},{\"id\":\"blinds\",\"hu\":\"Redőny\",\"en\":\"Roller shutter\"},{\"id\":\"curtain\",\"hu\":\"Függöny\",\"en\":\"Curtain\"},{\"id\":\"door\",\"hu\":\"Ajtó\",\"en\":\"Door\"},{\"id\":\"window\",\"hu\":\"Ablak\",\"en\":\"Window\"},{\"id\":\"motion\",\"hu\":\"Mozgásérzékelő\",\"en\":\"Motion sensor\"},{\"id\":\"presence\",\"hu\":\"Jelenlétérzékelő\",\"en\":\"Presence sensor\"},{\"id\":\"water-leak\",\"hu\":\"Vízszivárgás\",\"en\":\"Water leak\"},{\"id\":\"smoke\",\"hu\":\"Füstérzékelő\",\"en\":\"Smoke detector\"},{\"id\":\"alarm\",\"hu\":\"Riasztó\",\"en\":\"Alarm\"},{\"id\":\"lock\",\"hu\":\"Zár\",\"en\":\"Lock\"},{\"id\":\"irrigation\",\"hu\":\"Öntözés\",\"en\":\"Irrigation\"},{\"id\":\"garden-light\",\"hu\":\"Kerti világítás\",\"en\":\"Garden lighting\"},{\"id\":\"wall-light\",\"hu\":\"Fali / teraszlámpa\",\"en\":\"Wall / patio light\"},{\"id\":\"ceiling-light\",\"hu\":\"Mennyezeti világítás\",\"en\":\"Ceiling light\"},{\"id\":\"led-strip\",\"hu\":\"LED szalag\",\"en\":\"LED strip\"},{\"id\":\"home\",\"hu\":\"Otthon\",\"en\":\"At home\"},{\"id\":\"away\",\"hu\":\"Távollét\",\"en\":\"Away\"},{\"id\":\"night\",\"hu\":\"Éjszakai mód\",\"en\":\"Night mode\"},{\"id\":\"movie\",\"hu\":\"Mozi / film\",\"en\":\"Movie scene\"},{\"id\":\"relax\",\"hu\":\"Pihenés / hangulat\",\"en\":\"Relax scene\"},{\"id\":\"router\",\"hu\":\"Router / hálózat\",\"en\":\"Router / network\"}];\n"
"    const get = id => document.getElementById(id);\n"
"    let model = {schema: 1, consumers: [], cards: []};\n"
"    let catalog = [], catalogKey = '', loaded = false, fetching = false;\n"
"    let pending = false, waiting = false, remoteBusy = false, connectionBusy = false;\n"
"    let revision = 0, saveRevision = 0, currentSection = '';\n"
"    const domId = (entry, key) => 'home-' + currentSection + '-' + entry.id + '-' + key;\n"
"    const controls = [];\n"
"\n"
"    function notify(text, error = false) {\n"
"        const node = get('home-status');\n"
"        node.textContent = text;\n"
"        node.className = error ? 'feedback-error' : '';\n"
"    }\n"
"    function create(tag, text) {\n"
"        const node = document.createElement(tag);\n"
"        if (text !== undefined) node.textContent = text;\n"
"        return node;\n"
"    }\n"
"    function busy() { return !loaded || pending || waiting || remoteBusy || connectionBusy; }\n"
"    function buttons() {\n"
"        for (const control of controls) control.disabled = busy() || !!control.homeFixed;\n"
"        get('home-save').disabled = busy();\n"
"        get('home-add-consumer').disabled = busy() || model.consumers.length >= 12;\n"
"        get('home-add-card').disabled = busy() || model.cards.length >= 12;\n"
"    }\n"
"    function field(parent, title, entry, key, type = 'text', optional = false) {\n"
"        const label = create('label', title), input = create('input');\n"
"        input.type = type;\n"
"        if (type === 'checkbox') input.checked = !!entry[key];\n"
"        else input.value = entry[key] ?\? '';\n"
"        if (type === 'number') input.step = 'any';\n"
"        if (type === 'text') input.maxLength = key === 'name' ? 80 : key === 'unit' ? 16 : 36;\n"
"        input.id = domId(entry, key);\n"
"        input.oninput = input.onchange = () => {\n"
"            entry[key] = type === 'checkbox' ? input.checked : type === 'number' ?\n"
"                (optional && !input.value.trim() ? null : input.value.trim() ? Number(input.value) : NaN) : input.value;\n"
"        };\n"
"        controls.push(input);\n"
"        label.append(input); parent.append(label);\n"
"        return input;\n"
"    }\n"
"    function select(parent, title, entry, key, choices) {\n"
"        const label = create('label', title), input = create('select');\n"
"        input.id = domId(entry, key);\n"
"        for (const [value, text] of choices) {\n"
"            const option = create('option', text); option.value = value; input.append(option);\n"
"        }\n"
"        if (entry[key] && !choices.some(([value]) => value === entry[key])) {\n"
"            const retained = create('option', 'Korábban párosított / nem található: ' + entry[key]);\n"
"            retained.value = entry[key]; input.append(retained);\n"
"        }\n"
"        input.value = entry[key] ?\? '';\n"
"        input.onchange = () => { entry[key] = input.value; };\n"
"        controls.push(input); label.append(input); parent.append(label);\n"
"        return input;\n"
"    }\n"
"    function stateChoices(control = false, pulse = false) {\n"
"        const choices = [['', 'Nincs hozzárendelve']], seen = new Set();\n"
"        const room = get('home-room').value, category = get('home-category').value;\n"
"        for (const item of catalog) {\n"
"            if ((room && JSON.stringify(item.room || '') !== room) ||\n"
"                (category && JSON.stringify(item.category || '') !== category)) continue;\n"
"            if (control && !(item.secured === false && (item.type === 'Switch' ||\n"
"                (pulse && ['Pushbutton', 'TimedSwitch'].includes(item.type))))) continue;\n"
"            const uuid = control ? item.control_uuid : item.uuid;\n"
"            if (!uuid || seen.has(uuid)) continue;\n"
"            seen.add(uuid);\n"
"            choices.push([uuid, (item.name || 'Névtelen') + ' (' + (item.room || '–') + ' / ' +\n"
"                (item.category || '–') + ')' + (control ? ' · vezérlés' : ' · ' + (item.state || 'állapot'))]);\n"
"        }\n"
"        return choices;\n"
"    }\n"
"    function source(parent, entry) {\n"
"        const wrapper = {id: entry.id, uuid: entry.source?.uuid || ''};\n"
"        const input = select(parent, 'Loxone visszajelző állapot', wrapper, 'uuid', stateChoices());\n"
"        input.onchange = () => { entry.source.uuid = input.value; };\n"
"        const scale = field(parent, 'Szorzó (W → kW: 0.001)', entry.source, 'scale', 'number');\n"
"        scale.id = domId(entry, 'scale');\n"
"        if (entry.type === 'value') {\n"
"            const offset = field(parent, 'Eltolás', entry.source, 'offset', 'number');\n"
"            offset.id = domId(entry, 'offset');\n"
"        }\n"
"        if (entry.type === 'switch') scale.homeFixed = true;\n"
"    }\n"
"    function render() {\n"
"        controls.length = 0;\n"
"        for (const section of ['consumers', 'cards']) {\n"
"            currentSection = section;\n"
"            const target = get('home-' + section); target.replaceChildren();\n"
"            for (const entry of model[section]) {\n"
"                const box = create('fieldset'), legend = create('legend', entry.name || 'Új elem');\n"
"                box.append(legend);\n"
"                const grid = create('div'); grid.className = 'grid'; box.append(grid);\n"
"                field(grid, 'Név', entry, 'name');\n"
"                select(grid, 'Ikon', entry, 'icon', icons.map(icon => [icon.id, icon.hu]));\n"
"                if (section === 'consumers') {\n"
"                    source(grid, entry);\n"
"                    field(grid, 'Átlagos üzemi teljesítmény (kW, opcionális)', entry, 'average_kw', 'number', true);\n"
"                    field(grid, 'Indítás javasolható (alapból kikapcsolva)', entry, 'suggest_start', 'checkbox');\n"
"                } else {\n"
"                    const type = select(grid, 'Kártyatípus', entry, 'type', [\n"
"                        ['value', 'Érték'], ['pulse', 'Pillanatnyi gomb'], ['switch', 'Be/ki kapcsoló']]);\n"
"                    type.onchange = () => {\n"
"                        entry.type = type.value;\n"
"                        if (entry.type === 'switch') { entry.source.scale = 1; entry.source.offset = 0; }\n"
"                        render();\n"
"                    };\n"
"                    if (entry.type !== 'pulse') source(grid, entry);\n"
"                    if (entry.type !== 'value')\n"
"                        select(grid, 'Vezérelhető Loxone objektum', entry, 'control_uuid', stateChoices(true, entry.type === 'pulse'));\n"
"                    if (entry.type === 'value') {\n"
"                        field(grid, 'Mértékegység', entry, 'unit');\n"
"                        const decimals = field(grid, 'Tizedesek (0–3)', entry, 'decimals', 'number');\n"
"                        decimals.min = 0; decimals.max = 3; decimals.step = 1;\n"
"                        field(grid, 'Alsó figyelmeztetési határ (opcionális)', entry, 'warning_low', 'number', true);\n"
"                        field(grid, 'Felső figyelmeztetési határ (opcionális)', entry, 'warning_high', 'number', true);\n"
"                        field(grid, 'Figyelmeztetés színe', entry, 'warning_color', 'color');\n"
"                    }\n"
"                }\n"
"                const remove = create('button', 'Elem törlése'); remove.type = 'button';\n"
"                remove.onclick = () => { model[section] = model[section].filter(item => item.id !== entry.id); render(); };\n"
"                controls.push(remove); box.append(remove); target.append(box);\n"
"            }\n"
"        }\n"
"        buttons();\n"
"    }\n"
"    function filters() {\n"
"        for (const [id, key, title] of [['home-room', 'room', 'Összes helyiség'], ['home-category', 'category', 'Összes funkció']]) {\n"
"            const node = get(id), previous = node.value;\n"
"            node.replaceChildren();\n"
"            const blank = create('option', title); blank.value = ''; node.append(blank);\n"
"            const values = [...new Set(catalog.map(item => item[key] || ''))].sort((a,b) => a.localeCompare(b, 'hu'));\n"
"            for (const value of values) {\n"
"                const option = create('option', value || 'Nincs megadva'); option.value = JSON.stringify(value); node.append(option);\n"
"            }\n"
"            node.value = values.some(value => JSON.stringify(value) === previous) ? previous : '';\n"
"        }\n"
"    }\n"
"    function add(section) {\n"
"        if (busy() || model[section].length >= 12) return;\n"
"        let serial = 1;\n"
"        while (model[section].some(item => item.id === 'item-' + serial)) serial++;\n"
"        const entry = {id: 'item-' + serial, name: '', icon: icons[0].id, source: {uuid: '', scale: 1, offset: 0}};\n"
"        if (section === 'consumers') Object.assign(entry, {average_kw: null, suggest_start: false});\n"
"        else Object.assign(entry, {type: 'value', control_uuid: '', unit: '', decimals: 1,\n"
"            warning_low: null, warning_high: null, warning_color: '#E66B6B'});\n"
"        model[section].push(entry); render();\n"
"    }\n"
"    const uuidValid = value => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{16}$/i.test(value || '');\n"
"    function validate() {\n"
"        for (const section of ['consumers', 'cards']) for (const entry of model[section]) {\n"
"            const title = entry.name || 'Névtelen elem';\n"
"            if (!entry.name.trim() || new TextEncoder().encode(entry.name).length > 80 || /[\\x00-\\x1f\\x7f]/.test(entry.name)) return title + ': adj meg legfeljebb 80 bájtos nevet.';\n"
"            if (!icons.some(icon => icon.id === entry.icon)) return title + ': válassz ikont.';\n"
"            if (entry.type !== 'pulse' && (!uuidValid(entry.source.uuid) || !Number.isFinite(entry.source.scale) ||\n"
"                !entry.source.scale || Math.abs(entry.source.scale) > 1e6 || !Number.isFinite(entry.source.offset) || Math.abs(entry.source.offset) > 1e6))\n"
"                return title + ': hiányzó állapotpárosítás vagy érvénytelen átalakítás.';\n"
"            if (section === 'consumers') {\n"
"                if (entry.source.offset !== 0) return title + ': a fogyasztói teljesítmény eltolása nulla legyen.';\n"
"                if (entry.average_kw !== null && (!Number.isFinite(entry.average_kw) || entry.average_kw <= 0 || entry.average_kw > 1000)) return title + ': az üzemi teljesítmény 0 és 1000 kW közötti pozitív szám legyen.';\n"
"            } else {\n"
"                if (entry.type !== 'value' && !uuidValid(entry.control_uuid)) return title + ': válassz vezérelhető objektumot; az állapot UUID nem parancscél.';\n"
"                if (entry.type === 'switch' && (entry.source.scale !== 1 || entry.source.offset !== 0)) return title + ': a kapcsoló állapota nem skálázható.';\n"
"                if (entry.type === 'value' && (!Number.isInteger(entry.decimals) || entry.decimals < 0 || entry.decimals > 3 ||\n"
"                    new TextEncoder().encode(entry.unit || '').length > 16 ||\n"
"                    /[\\x00-\\x1f\\x7f]/.test(entry.unit || '') ||\n"
"                    !/^#[0-9a-f]{6}$/i.test(entry.warning_color) ||\n"
"                    [entry.warning_low, entry.warning_high].some(value => value !== null && !Number.isFinite(value)) ||\n"
"                    (entry.warning_low !== null && entry.warning_high !== null && entry.warning_low > entry.warning_high)))\n"
"                    return title + ': érvénytelen mértékegység, tizedes vagy figyelmeztetési határ.';\n"
"            }\n"
"        }\n"
"        return '';\n"
"    }\n"
"    async function refresh(nextCatalog = [], otherBusy = false) {\n"
"        if (!get('home-editor') || fetching) return;\n"
"        fetching = true; connectionBusy = otherBusy;\n"
"        try {\n"
"            const response = await apiFetch('/api/loxone/home', {cache: 'no-store'});\n"
"            if (!response.ok) throw Error(await response.text());\n"
"            const state = await response.json();\n"
"            const first = !loaded;\n"
"            if (first) {\n"
"                model = {schema: 1, consumers: state.consumers || [], cards: state.cards || []};\n"
"                for (const entry of model.cards) {\n"
"                    entry.source ||= {uuid: '', scale: 1, offset: 0};\n"
"                    entry.control_uuid ||= '';\n"
"                    entry.unit ?\?= '';\n"
"                    entry.decimals ?\?= 1;\n"
"                    entry.warning_low ?\?= null;\n"
"                    entry.warning_high ?\?= null;\n"
"                    entry.warning_color ||= '#E66B6B';\n"
"                }\n"
"                loaded = true;\n"
"            }\n"
"            revision = state.revision; remoteBusy = !!state.busy;\n"
"            if (waiting && !remoteBusy) {\n"
"                waiting = false;\n"
"                notify(state.status || (revision > saveRevision ? 'Otthon-beállítások elmentve.' : 'A mentés nem fejeződött be.'), revision <= saveRevision);\n"
"            } else if (first) notify(state.status || 'Legfeljebb 12 fogyasztó és 12 Otthon-kártya állítható be.');\n"
"            const nextKey = JSON.stringify(nextCatalog);\n"
"            if (first || nextKey !== catalogKey) {\n"
"                catalog = nextCatalog; catalogKey = nextKey; filters(); render();\n"
"            }\n"
"        } catch (error) {\n"
"            notify('Otthon-beállítások: ' + (error.name === 'AbortError' ? 'az eszköz nem válaszol.' : error.message), true);\n"
"        } finally { fetching = false; buttons(); }\n"
"    }\n"
"    async function save() {\n"
"        if (busy()) return;\n"
"        const error = validate(); if (error) { notify(error, true); return; }\n"
"        pending = true; buttons(); notify('Otthon-beállítások mentése…');\n"
"        saveRevision = revision;\n"
"        try {\n"
"            const response = await apiFetch('/api/loxone/home', {method: 'POST',\n"
"                headers: {'Content-Type': 'application/json', 'X-Zolee-Loxone': '1'}, body: JSON.stringify(model)});\n"
"            if (!response.ok) throw Error(await response.text());\n"
"            waiting = true;\n"
"            await refresh(catalog, connectionBusy);\n"
"        } catch (error) { notify('A mentés eredményét ellenőrizd: ' + error.message, true); }\n"
"        finally { pending = false; buttons(); }\n"
"    }\n"
"    if (get('home-editor')) {\n"
"        get('home-add-consumer').onclick = () => add('consumers');\n"
"        get('home-add-card').onclick = () => add('cards');\n"
"        get('home-save').onclick = save;\n"
"        get('home-room').onchange = get('home-category').onchange = render;\n"
"        buttons();\n"
"    }\n"
"    return {refresh};\n"
"})();\n"
"\n"
"'use strict';\n"
"const fields=[['PowerGrid','Hálózati teljesítmény (kW)',1],['PowerBat','Akku teljesítmény (kW)',1],['PowerPV','Napelem teljesítmény (kW)',1],['PowerFull','Ház fogyasztása (kW)',1],['SocBat','Töltöttség (%)',1],['Status','Rendszerállapot (1–4)',1],['NightMode','Éjszakai mód (0/1)',1],['BatteryTemperature','Akku hőmérséklete (°C)',1],['Temperature','Külső hőmérséklet (°C)'],['WindSpeed','Szélsebesség (km/h)'],['HasSunRadiation','Napsugárzás (0/1)'],['HasPrecipitation','Csapadék (0/1)'],['SunAzimuth','Nap azimutja (°)'],['SunAltitude','Nap magassága (°)'],['Sunrise','Napkelte (perc éjféltől)'],['Sunset','Napnyugta (perc éjféltől)']];\n"
"const sunFields=['SunAzimuth','SunAltitude','Sunrise','Sunset'];\n"
"const $=id=>document.getElementById(id);let catalog=[],catalogSnapshot='',initialized=false,busy=false,serverBusy=false,requestPending=false,feedback='';\n"
"for(const [key,label,required] of fields){const row=document.createElement('tr');const title=document.createElement('td');title.textContent=label+(required?' *':'');row.append(title);for(const type of ['uuid','scale','offset']){const cell=document.createElement('td'),el=document.createElement(type==='uuid'?'select':'input');el.id=key+'_'+type;if(type!=='uuid'){el.type='number';el.step='any';el.value=type==='scale'?'1':'0';}cell.append(el);row.append(cell);}$('mappings').append(row);}\n"
"function filters(){for(const [id,property,label] of [['room-filter','room','Összes helyiség'],['category-filter','category','Összes funkció']]){const select=$(id),selected=select.value;select.replaceChildren();const all=document.createElement('option');all.value='';all.textContent=label;select.append(all);const names=[...new Set(catalog.map(c=>c[property]||''))].sort((a,b)=>a.localeCompare(b,'hu'));for(const name of names){const o=document.createElement('option');o.value=JSON.stringify(name);o.textContent=name||(property==='room'?'Nincs helyiség':'Nincs funkció');select.append(o);}select.value=names.some(name=>JSON.stringify(name)===selected)?selected:'';}}\n"
"function options(){const room=$('room-filter').value,category=$('category-filter').value;for(const [key] of fields){const select=$(key+'_uuid'),selected=select.value;select.replaceChildren();let found=false;const blank=document.createElement('option');blank.value='';blank.textContent='Nincs hozzárendelve';select.append(blank);for(const c of catalog){if(!c.uuid)continue;if(c.uuid!==selected&&((room&&JSON.stringify(c.room||'')!==room)||(category&&JSON.stringify(c.category||'')!==category)))continue;const o=document.createElement('option');o.value=c.uuid;o.textContent=(c.name||'Névtelen')+' ('+(c.room||'–')+' / '+(c.category||'–')+')'+(c.state?' · '+c.state:'');select.append(o);if(c.uuid===selected)found=true;}if(selected&&!found){const o=document.createElement('option');o.value=selected;o.textContent='Korábban párosított / nem található: '+selected;select.append(o);}select.value=selected;}}\n"
"function values(){const mappings={};for(const [key] of fields)mappings[key]={uuid:$(key+'_uuid').value,scale:Number($(key+'_scale').value),offset:Number($(key+'_offset').value)};return {host:$('host').value.trim(),port:Number($('port').value),tls:$('tls').checked,ca_pem:$('ca_pem').value.trim(),username:$('username').value,password:$('password').value||null,mappings};}\n"
"function message(text,error=false){const changed=$('status').textContent!==text;for(const id of ['status','save-status']){const el=$(id);if(el){el.textContent=text;el.className=error?'feedback-error':'';}}if(error&&changed)$('status').scrollIntoView?.({block:'nearest',behavior:'smooth'});}\n"
"function buttons(){busy=serverBusy||requestPending;$('test').disabled=busy;$('save').disabled=busy;}\n"
"async function apiFetch(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{return await fetch(url,{...options,signal:controller.signal});}finally{clearTimeout(timer);}}\n"
"function validate(action){\n"
" const data=values();\n"
" if(!data.host||!data.username)return 'Add meg a Miniserver címét és a felhasználónevet.';\n"
" if(!/^[a-z0-9.-]+$/i.test(data.host))return 'A Miniserver mezőbe csak IP-címet vagy gépnevet írj, http:// előtag és útvonal nélkül.';\n"
" if(!Number.isInteger(data.port)||data.port<1||data.port>65535)return 'A port 1 és 65535 közötti egész szám legyen.';\n"
" if(data.tls&&!data.ca_pem.includes('-----BEGIN CERTIFICATE-----'))return 'A WSS be van kapcsolva, de nincs megadva CA-tanúsítvány. Add meg a PEM-tanúsítványt, vagy helyi WS-kapcsolathoz kapcsold ki a WSS jelölést és használd a Miniserver HTTP-portját (általában 80).';\n"
" for(const [key,label,required] of fields){\n"
"  if(action==='save'&&required&&!data.mappings[key].uuid)return 'Hiányzó kötelező párosítás: '+label+'. Előbb kérd le az adatlistát, majd válaszd ki a megfelelő állapotot.';\n"
"  if(!$(key+'_scale').value.trim()||!$(key+'_offset').value.trim()||!Number.isFinite(data.mappings[key].scale)||!Number.isFinite(data.mappings[key].offset))return 'Érvénytelen szorzó vagy eltolás: '+label+'.';\n"
" }\n"
" if(action==='save'){const count=sunFields.filter(key=>data.mappings[key].uuid).length;if(count&&count!==4)return 'A nappályához mind a négy adatot párosítsd: azimut, magasság, napkelte és napnyugta.';}\n"
" return '';\n"
"}\n"
"async function refresh(){try{\n"
" const r=await apiFetch('/api/loxone',{cache:'no-store'});if(!r.ok)throw Error(await r.text());const state=await r.json();\n"
" if(!initialized){for(const key of ['host','port','username','ca_pem'])$(key).value=state[key]?\?'';$('tls').checked=state.tls;for(const [key] of fields){const m=state.mappings[key];if(m){const o=document.createElement('option');o.value=m.uuid;o.textContent=m.uuid;$(key+'_uuid').append(o);$(key+'_uuid').value=m.uuid;$(key+'_scale').value=m.scale;$(key+'_offset').value=m.offset;}}$('password').placeholder=state.has_password?'Mentett jelszó változatlan':'Add meg a jelszót (másik kijelzőn újra szükséges)';initialized=true;}\n"
" const next=JSON.stringify(state.catalog||[]);if(next!==catalogSnapshot){catalogSnapshot=next;catalog=(state.catalog||[]).slice().sort((a,b)=>(a.name||'').localeCompare(b.name||'','hu')||(a.state||'').localeCompare(b.state||'','hu'));filters();options();}\n"
" serverBusy=!!state.busy;buttons();message(feedback||state.status,!!feedback);\n"
" if(typeof LoxoneHome!=='undefined')await LoxoneHome.refresh(catalog,serverBusy);\n"
" }catch(e){if(!feedback)message('Kapcsolati hiba: '+(e.name==='AbortError'?'Az eszköz nem válaszolt 15 másodpercen belül.':e.message),true);}\n"
"}\n"
"async function submit(action){\n"
" if(busy)return;\n"
" if(!initialized){feedback='Az eszköz beállításait még nem sikerült betölteni. Ellenőrizd az eszközkapcsolatot, majd töltsd újra az oldalt.';message(feedback,true);return;}\n"
" feedback=validate(action);if(feedback){message(feedback,true);return;}\n"
" requestPending=true;buttons();message(action==='save'?'Mentés folyamatban…':'Kapcsolat tesztelése…');\n"
" try{const r=await apiFetch('/api/loxone/'+action,{method:'POST',headers:{'Content-Type':'application/json','X-Zolee-Loxone':'1'},body:JSON.stringify(values())});if(!r.ok)throw Error(await r.text());await refresh();}\n"
" catch(e){feedback=e.name==='AbortError'?'Az eszköz nem válaszolt 15 másodpercen belül. Ellenőrizd a kapcsolatot, majd próbáld újra.':e.message;message(feedback,true);}\n"
" finally{requestPending=false;buttons();}\n"
"}\n"
"$('tls').addEventListener('change',()=>{if($('tls').checked&&$('port').value==='80')$('port').value='443';else if(!$('tls').checked&&$('port').value==='443')$('port').value='80';});\n"
"$('room-filter').addEventListener('change',options);$('category-filter').addEventListener('change',options);$('test').onclick=()=>submit('test');$('save').onclick=()=>submit('save');refresh();setInterval(refresh,2000);\n"
"</script></html>\n";
